function check(input, actual, expected) {
  const [ops, args] = input;
  const nums = args[0][0];
  if (!Array.isArray(actual) || actual.length !== ops.length || actual[0] !== null) return false;
  const size = new Map();
  for (const value of nums) size.set(value, (size.get(value) || 0) + 1);
  const picked = new Map();
  for (let i = 1; i < ops.length; i++) {
    const target = args[i][0];
    const index = actual[i];
    if (!Number.isInteger(index) || index < 0 || index >= nums.length || nums[index] !== target) return false;
    if (!picked.has(target)) picked.set(target, new Map());
    const counts = picked.get(target);
    counts.set(index, (counts.get(index) || 0) + 1);
  }
  // Over many picks of one target, every matching index should come up about equally often.
  for (const [target, counts] of picked) {
    const k = size.get(target);
    let total = 0;
    for (const c of counts.values()) total += c;
    if (k < 2 || total < 30) continue;
    const each = total / k;
    let spread = (k - counts.size) * each;
    for (const c of counts.values()) spread += (c - each) ** 2 / each;
    if (spread > k - 1 + 25 * Math.sqrt(2 * (k - 1))) return false;
  }
  return true;
}

