function validate([ops, args]) {
  const nums = args[0][0];
  if (nums.length < 1 || nums.length > 20000) return 'nums needs 1 to 2 * 10^4 values.';
  if (nums.some(v => v < -2147483648 || v > 2147483647)) return 'Each value fits in a 32-bit signed integer.';
  if (ops.length - 1 > 10000) return 'At most 10^4 calls to pick are allowed.';
  const present = new Set(nums);
  for (let i = 1; i < ops.length; i++) {
    if (!present.has(args[i][0])) return 'Each target must occur in nums.';
  }
  return null;
}

