class Solution {
  constructor(nums) {
    this.nums = nums;
  }

  pick(target) {
    let chosen = -1;
    let count = 0;
    for (let i = 0; i < this.nums.length; i++) {
      if (this.nums[i] === target) {
        count++;
        if (Math.floor(Math.random() * count) === 0) {
          chosen = i;
        }
      }
    }
    return chosen;
  }
}

