class Solution {
  constructor(nums) {
    // Every value's indices, gathered once.
    this.positions = new Map();
    nums.forEach((value, i) => {
      if (!this.positions.has(value)) this.positions.set(value, []);
      this.positions.get(value).push(i);
    });
  }
  pick(target) {
    const list = this.positions.get(target);
    return list[Math.floor(Math.random() * list.length)];
  }
}

