function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 2000 : 1 + pick(8);
  const kinds = size === 'large' ? [1, 5, 50, 2000][pick(4)] : 1 + pick(4);
  // A few distinct values, sometimes at the 32-bit extremes, so duplicates are common.
  const palette = Array.from({ length: kinds }, () => rand() < 0.2 ? [-2147483648, 2147483647][pick(2)] : pick(41) - 20);
  const nums = Array.from({ length: n }, () => palette[pick(kinds)]);
  const count = size === 'large' ? 400 : 1 + pick(20);
  const ops = ['Solution'], args = [[nums]];
  for (let i = 0; i < count; i++) {
    ops.push('pick');
    args.push([nums[pick(n)]]);
  }
  return [ops, args];
}
